def append(list1, list2):
    result = []
    for item in list1:
        result.append(item)
    for item in list2:
        result.append(item)
    return result


def concat(lists):
    result = []
    for inner in lists:
        for item in inner:
            result.append(item)
    return result


concatenate = concat


def filter(function, items):
    result = []
    for item in items:
        if function(item):
            result.append(item)
    return result


def length(items):
    count = 0
    for _ in items:
        count = count + 1
    return count


def map(function, items):
    result = []
    for item in items:
        result.append(function(item))
    return result


def foldl(function, items, initial):
    accumulator = initial
    for item in items:
        accumulator = function(accumulator, item)
    return accumulator


def foldr(function, items, initial):
    return foldl(function, reverse(items), initial)


def reverse(items):
    copied = []
    for item in items:
        copied.append(item)

    result = []
    index = length(copied) - 1
    while index >= 0:
        result.append(copied[index])
        index = index - 1
    return result
